"""Deterministic analysis of the frozen, deduplicated mining dataset."""
from collections import Counter, defaultdict
from difflib import SequenceMatcher
import json
from pathlib import Path
import statistics

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'docs/trajectory-analysis'
d=json.loads((OUT/'dataset.json').read_text())
sessions={s['session_id']:s['state'] for s in json.loads((OUT/'replay_sessions.json').read_text())}
real=[t for t in d['turns'] if t['provenance']=='real_provider_observed']
free=[t for t in real if t['player']['free_input']]
rank=[s for s in d['spans'] if s.get('name')=='decision.rank' and s.get('provider')=='jev']
def md(name,text):
    path=ROOT/name;path.parent.mkdir(parents=True,exist_ok=True);path.write_text(text+'\n')
def table(headers,rows):
    return '| '+' | '.join(headers)+' |\n| '+' | '.join(['---']*len(headers))+' |\n'+'\n'.join('| '+' | '.join(str(c).replace('\n',' ').replace('|','/') for c in r)+' |' for r in rows)+'\n'
issues=defaultdict(list)
for t in real:
    error=t['branch'].get('last_error') or '';bid=t['turn_id'];outcome=(t['director']['output'] or {}).get('outcome',{});tr=t['skills']['triggered'];world=t['context'].get('world_before') or {}
    if 'patch path' in error or 'operation' in error or 'item not owned' in error: issues['proposal_contract'].append(bid)
    if 'narrative leak' in error: issues['truth_guard_false_positive_historical'].append(bid)
    if any(x in error.lower() for x in ('character reference', 'reference pack', 'explicit shot cast', 'reference resolver')): issues['character_reference'].append(bid)
    if '403' in error or 'BILLING' in error: issues['provider_billing'].append(bid)
    if 'validation error' in error: issues['director_schema'].append(bid)
    if any(x.get('skill')=='inventory' and x.get('stage')=='USED' and x.get('action')=='add' for x in tr):issues['inventory_used_as_add'].append(bid)
    if any(x.get('skill')=='inventory' and x.get('action')=='remove' and x.get('target') not in world.get('inventory',[]) for x in tr):issues['remove_unowned_item'].append(bid)
    if t['record_kind']=='player_turn' and outcome.get('evidence') and not any(x.get('skill')=='clue-system' for x in tr):issues['evidence_without_clue_review_required'].append(bid)
    if t['branch']['status']=='CANONICAL' and t['player']['free_input'] and not outcome.get('ops') and not tr:issues['action_without_state_change_review_required'].append(bid)
    if t['player']['free_input']:issues['jev_observation_not_in_director_prompt'].append(bid)
latencies=defaultdict(list)
for s in d['spans']:
    if s.get('duration_ms',0)>0:latencies[s.get('provider') or 'unknown'].append(s['duration_ms'])
profile={'real_observed_sessions':sum(s['provenance']=='real_provider_observed' for s in d['session_index']), 'real_player_turns':sum(t['record_kind']=='player_turn' for t in real),'real_openings':sum(t['record_kind']=='opening' for t in real),'real_speculative_branches':sum(t['record_kind']=='speculative_branch' for t in real),'real_free_branches':len(free),'real_canonical_free':sum(t['branch']['status']=='CANONICAL' for t in free),'real_failed_branches':sum(t['branch']['status']=='FAILED' for t in real),'real_skill_trigger_counts':dict(Counter(x['skill'] for t in real for x in t['skills']['triggered'])),'rank_calls':len(rank),'other_over_50_percent':sum(s['output'].get('ranked',{}).get('OTHER',0)>.5 for s in rank),'provider_latency_observed':{k:{'n':len(v),'median_ms':statistics.median(v),'max_ms':max(v)} for k,v in latencies.items()},'issues':dict(issues)}
(OUT/'baseline_metrics.json').write_text(json.dumps(profile,ensure_ascii=False,indent=2)+'\n')
md('docs/trajectory-analysis/TRAJECTORY_SOURCE_INDEX.md', '# Trajectory Source Index\n\nStart SHA: `'+d['start_sha']+'`. Dataset capture: '+d['captured_at']+'.\n\nRead-only repeatable-read database capture plus 474 JSON/JSONL evidence sources. Exact paths, hashes, sessions, branch IDs, timestamps, event types, provenance and completeness are in [source_index.json](source_index.json). Domain IDs deduplicate repeated screenshots/checkpoints. `replay_sessions.json` freezes source state; `dataset.json` normalizes causal records.\n\n**A session with real providers is not proof of a completed real-media E2E.** Mixed/mock/unknown data are separate; failed requests and text-mode recovery are retained. Sessions from evidence only are included once. No missing before-state, tokens or trigger labels are invented.\n\n'+table(['Session','Scenario','Provenance','Branches','Player input events','Sources'],[[s[k] for k in ['session_id','scenario_id','provenance','branches','player_inputs','source_count']] for s in d['session_index']]))
md('docs/trajectory-analysis/FAILURE_TAXONOMY.md','# Trajectory Failure Taxonomy\n\nCounts are affected branch IDs, not independent users. Historical failures may already be fixed; hypotheses are not labeled confirmed defects.\n\n'+table(['Class','Count','Examples'],[[k,len(v),', '.join(v[:6])] for k,v in issues.items()])+'\n\nP0: contradictory inventory operations / invented possession; state and published identity must remain controlled. P1: evidence without gameplay updates, Jev context starvation, invisible skill execution, continuity/agency mismatch. P2: transport/schema recovery and character refs already addressed in earlier commits. Trace loss is a confirmed current infrastructure defect: DB spans=0, while 467 spans survive in evidence; `Tracer.emit` never called `persist`.')
md('docs/trajectory-analysis/GAMEPLAY_CHAIN_PROFILE.md','# Gameplay Chain Profile\n\n'+table(['Metric','Value'],[[k,v] for k,v in profile.items() if k not in ['issues','provider_latency_observed']])+'\n\n'+table(['Provider','Observed calls with latency','Median ms','Max ms'],[[k,v['n'],v['median_ms'],v['max_ms']] for k,v in profile['provider_latency_observed'].items()])+'\n\nCounts are lower bounds: 77 recovered provider.text records are not the entire execution history. Branch routes omit retries and session-level candidate/intent calls. Zero duration means missing, not instantaneous. Timelines in dataset.json retain phase timestamps and canonical events. created-to-ready includes queue/media; it is not Jev latency. K-ready uses epoch branch_ready events; deferred text-ready is separate from media-ready. Historical ledger has no reliable branch correlation for every request: do not assign all 43 H3 operations to canonical turns or call all speculative media waste. Human and automation operation ownership is not recorded. Future traces require turn_id, purpose, model request ID, usage, proposal decisions, explicit before/after snapshots.')
md('docs/trajectory-analysis/FREE_ACTION_ANALYSIS.md','# Free Action Analysis\n\nReal-provider-observed FREE branches: '+str(len(free))+'. Canonical: '+str(profile['real_canonical_free'])+'. This is branch acceptance, not semantic fidelity. None is stored as a recommendation branch; failures and clarifications must not be counted as faithful outcomes.\n\n'+table(['Branch','Raw input','Result','Skills'],[[t['turn_id'],t['player']['raw_input'],t['branch']['status'],','.join(x['skill'] for x in t['skills']['triggered'])] for t in free])+'\n\nFidelity rubric: EXACT preserves action/target/strategy and stated constraints; ACCEPTABLE respects a world-grounded obstruction; DISTORTED loses a material part; OVERRIDDEN substitutes an unsupported action. Human/critic annotations must cite evidence, with UNKNOWN for absent output. Examples: br_00012_e5b104 preserves the alternative power/maintenance strategy, but state location is questionable. br_00078_d75c60 describes investigation starting rather than producing requested evidence. br_00335_aa08da accepts an unowned rocket and adds an unrequested unconscious companion. br_00049_f32ffd says the story ends but has no ending proposal. These are separate intent, world-consistency, and ending-contract dimensions.\n\nConfirmed code defect: `_plan_free_action` received Jev observation / confirmed strategy but did not put either into the Director prompt. This is discarded semantic work, not proof of four redundant LLM calls. Recommendation path already avoids a second FREE planning call through director_result reuse.')
md('docs/trajectory-analysis/TOPK_ANALYSIS.md','# Top-K Analysis\n\nReal Jev ranking calls recovered: '+str(len(rank))+'. OTHER > 0.5: '+str(profile['other_over_50_percent'])+'. Ranking input contains only location ID, inventory, clues and empty raw_player_input; missing current beat, readable location, relationships, pressure, player preference. OTHER is discarded during sorting. This is stronger evidence of context starvation than of semantic duplication.\n\n'+table(['Session','Candidates','OTHER'],[[s.get('session_id'),'; '.join(s['input']['candidates']),s['output'].get('ranked',{}).get('OTHER')] for s in rank])+'\n\nCandidates generally contain investigation/social/rescue/withdrawal alternatives. No validated corpus establishes frequent synonym-only triples. Do not add a separate diversity model call or force absurd choices. Evaluate lexical similarity as a screening proxy only; preserve Jev rank and report OTHER uncertainty. Exact normalized duplicate filtering and richer ranking context are justified; semantic MMR requires a labeled benchmark before deployment.')
md('docs/trajectory-analysis/CONTEXT_ANALYSIS.md','# Context Analysis\n\nDirector `_scenario_brief` includes complete published player/NPC dictionaries with asset metadata as well as last four outcome texts and full presented narratives. Repeated asset URLs/version data are irrelevant to action planning. Inventory/relationships/location must be retained. Narrative has a restricted ScenePacket but its output_contract additionally receives full scenario_brief (including hidden truth); currently OpenAI text transport ignores output_contract, so this is a future transport leak risk, not demonstrated current disclosure.\n\nJev has the opposite defect: raw location ID and insufficient dramatic context. Context projection will be role-specific and lossless for state/rules, strips only presentation/asset metadata for Director, gives Narrative only authorized facts plus canonical possessions/location, and gives Jev a bounded readable situation. Character knowledge/secrets are not indiscriminately made public. Character presence constraints, rules, anchor events and negative intent must survive projection.\n\nContext character counts are exactly measurable; tokens need an actual tokenizer/provider usage and cannot be inferred as chars/4. Live latency benefit remains unmeasured until text-only paired replay. No claim of fewer HTTP calls is justified merely by shorter prompts.')
md('docs/trajectory-analysis/TRAJECTORY_ANALYSIS.md','# Trajectory Analysis — research before implementation\n\n## Data Sources / Reconstruction\n'+json.dumps({k:v for k,v in profile.items() if k.startswith('real_')},ensure_ascii=False,indent=2)+'\n\n42 deduplicated sessions: 25 real-provider-observed, 14 mixed, 2 mock/fixture, 1 unknown. 214 branch records are not 214 player turns. Among real-provider-observed branches: 26 acted turns, 24 openings, 69 speculative branches. 474 source files, 467 recovered spans, 69 unique ledger operations. Database trace table is empty. Frozen read sets provide partial before-state; original canonical-after per turn cannot always be reconstructed without guessing. Missing observability is explicit.\n\n## Failure Taxonomy / Gameplay Bottlenecks\n1. Skill and provider traces disappear on restart.\n2. Inventory use can become acquisition; phantom possession then affects later turns.\n3. Discovered evidence lacks a clue proposal, so HUD/state lag behind prose.\n4. Jev ranking lacks current story context; high OTHER is ignored.\n5. Jev semantic observation and confirmed intent edits are dropped before Director.\n6. Canonical character metadata bloats planning context.\n7. Prose says movement/ending while the typed state remains unchanged.\n8. Secrets guard historical name matches blocked harmless openings (already fixed).\n9. Character reference and shot cast failures cost recovery time (existing fixes retained).\n10. Media/provider schema/billing errors obscure gameplay; do not treat media retry as agent intelligence failure.\n\n## Agent Redundancy / Skill Trigger Analysis\nJev classifies once, Director plans once, Narrative renders once: no evidence of four repeated understanding calls. Waste is discarded observation, repeated context, and uncontrolled proposal semantics. 34 real recorded mechanic triggers: inventory 13, clue 13, relationship 8. Missing trigger recall cannot be computed without labels; evidence_without_clue is a review queue, not an automatic false-negative count. qte is deterministic orchestration; Wish is preference state. Assembly/provider adapters are tools, not agent reasoning capabilities.\n\n## Free Action / Top-K / Context / State Consistency\nSee dedicated reports. Preserve StateManager as only commit authority. Speculative isolation must be tested rather than assumed from absence of errors. Add a semantic packet carrying original/confirmed action, quote-grounded constraints and existing Jev observations. Add one mechanic arbitration capability: explicit skill outputs checked as a group; reject contradictions rather than invent facts. Role-context projection is a deterministic tool used by these skills, not a cosmetic new Skill.\n\n## Latency / Cost\nHistorical spans contain partial latency/usage; no valid end-to-end median for every stage. No media requested during research. Never label unchanged stored Narrative as a newly generated improved story. Replay will distinguish recorded-output policy comparison, text-only counterfactual, regression fixtures and real historical evidence.\n\n## Prioritized hypotheses and implementation plan\nH1 Trace is lost because emit has no durability consumer; verify restart retrieval. H2 richer Jev context and action packet preserve previously discarded information; verify exact input invariants and blind text replay. H3 inventory proposal stage/action contradictions cause unsafe state; reproduce on frozen turns then reject/repair before Narrative. H4 asset metadata dominates planning context; measure lossless role projection.\n\nImplement four bounded changes: durable Skill Observatory; reusable Understand Free Action contract; Evidence-bound Mechanic Arbitration with one bounded Director correction; role-specific context plus exact-deduplicated choice ranking. Do not rewrite media or create 20 Skills. Before/after and limitations will be added to SKILL_EVALUATION.md after replay.')
md('docs/skills/AGENT_SKILL_OPPORTUNITIES.md','# Agent Skill Opportunities\n\nAnalysis recorded before runtime edits.\n\n'+table(['Capability','Evidence','Change','Benefit','Risk / Evaluation'],[
 ['Understand Free Action','16 real FREE branches; intent observation absent from Director prompt','Versioned ActionSemanticPacket; original plus confirmed constraints and Jev observation; no extra LLM','Retain player strategy, avoid repeated interpretation','Not a new generative agent; quote grounding + blind text replay'],
 ['Evidence-bound Mechanic Arbitration','2 USED+add triggers; 2 unowned removals; clues without typed proposals','One group policy checks skill outputs against known inventory, targets, lifecycle; bounded Director correction','Stop phantom items, duplicates, silent skill drops before media','Conservative rejection can reduce availability; replay accepted/rejected + regression'],
 ['Context-aware Choice Evaluation','4/11 Jev calls give OTHER > .5; minimal rank context','Shared role projection, current beat/preferences and dedupe; retain uncertainty in trace','Better-grounded ranking without another call','No claimed diversity lift without paired ratings'],
 ['Skill Observatory','0 DB spans, 467 recovered; SQL matches inventory% but emits skill.inventory','Persist all spans; query by skill ID/name; chain view; metrics with denominators','Contest demonstration and usable future evaluation','DB latency/failure isolation; restart regression'],
 ['Visual Continuity Critic','Prior Step reviews saved externally','Defer runtime integration; registry must distinguish reference policy from actual visual critic','Clear boundaries','No new media this round'],
 ['Narrative Continuity Critic','Movement/ending prose can diverge','Defer mandatory extra model call; annotate counterfactuals first','Future consistency','Latency + false rejection need labels']]))
print(json.dumps(profile,ensure_ascii=False,indent=2))
